<?php require 'vendor/autoload.php'; $app = require_once 'bootstrap/app.php'; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $visits = DB::table('ci_order_visits')->where('order_id', 266)->get(); foreach($visits as $visit) { if (preg_match('/^(\d{2}):00:00$/', $visit->visit_time, $matches)) { $tsId = (int)$matches[1]; if ($tsId > 0 && $tsId < 25) { DB::table('ci_order_visits')->where('id', $visit->id)->update(['visit_time' => sprintf('00:00:%02d', $tsId)]); echo 'Fixed visit ' . $visit->id . PHP_EOL; } } }
